import os,json,subprocess,stat
from pathlib import Path
targets={'fadego':'/etc/fadego-staging/','pink':'/etc/pink-iptv/'}
out={'targeted_references':{},'files_examined':0,'scan_complete':True,'legacy_metadata':{},'active_unit_envs':{},'service_health':{}}
roots=('/etc/systemd/system','/etc/nginx','/usr/local/bin','/usr/local/sbin','/etc/cron.d','/srv/projects/pink-iptv/backend','/srv/projects/pink-iptv/vpn','/srv/projects/pink-iptv/infra','/srv/projects/fadego/tools')
skip={'.git','.venv','node_modules','__pycache__','.next','.runtime','private','data','backups','artifacts','sessions','.cache','dist','build','archive'}
for top in roots:
 p=Path(top);matches=[]
 if not p.is_dir():continue
 for cur,dirs,files in os.walk(p):
  if len(Path(cur).relative_to(p).parts)>6:dirs[:]=[];continue
  dirs[:]=[d for d in dirs if d not in skip]
  for name in files:
   f=Path(cur)/name
   try:
    if not f.is_file() or f.is_symlink() or f.stat().st_size>150000:continue
    if f.suffix not in ('.py','.sh','.service','.conf','.timer','.js','.mjs','.cjs','.ts','.json','.yml','.yaml','.txt','.md','') and name!='fadego-password':continue
    if f.name.endswith('.env'):continue
    s=f.read_text(errors='replace')
    out['files_examined']+=1
    refs=[n for n,target in targets.items() if target in s]
    if refs:matches.append({'file':str(f),'refs':refs})
    if out['files_examined']>7500:out['scan_complete']=False;break
   except Exception:pass
  if not out['scan_complete']:break
 out['targeted_references'][top]=matches[:45]
 if not out['scan_complete']:break
for p in ('/etc/fadego-staging','/etc/pink-iptv'):
 d=Path(p);arr=[]
 if d.is_dir():
  for x in d.iterdir():
   st=x.lstat()
   arr.append({'name':x.name,'type':'link' if x.is_symlink() else 'dir' if x.is_dir() else 'file' if x.is_file() else 'other','mode':oct(stat.S_IMODE(st.st_mode)),'size_bytes':st.st_size})
 out['legacy_metadata'][p]=arr
for name in ('fadego-staging','pink-iptv-backend','pink-vpn','fadego-booking-email'):
 p=subprocess.run(['systemctl','cat',name],capture_output=True,text=True,timeout=10)
 out['active_unit_envs'][name]=[x.strip() for x in p.stdout.splitlines() if x.strip().startswith('EnvironmentFile=')]
 out['service_health'][name]=subprocess.run(['systemctl','is-active',name],capture_output=True,text=True,timeout=7).stdout.strip()
print(json.dumps(out,separators=(',',':')))
